    ('ecbf7685-f310-5632-bbf8-75ddfceb4736'::uuid, '779524fc-cd19-5138-adfa-23124b631580'::uuid, 'Quel bâtiment symbolise la capacité de projection de la marine française ?', 'mcq', '["Le porte-avions Charles de Gaulle","Le Belem","Le Mistral","Le France"]'::jsonb, 0, 'Seul porte-avions à propulsion nucléaire hors des États-Unis.', 8),
