    ('de2cd7fd-a710-54b6-aec4-770ca3e8143f'::uuid, 'c9863ee1-f130-5f83-85fd-81920bdca7aa'::uuid, 'Quelle ville chinoise s’est imposée comme place financière de rang mondial ?', 'mcq', '["Shanghai","Chengdu","Wuhan","Harbin"]'::jsonb, 0, 'Avec le quartier de Pudong comme vitrine.', 7),
