    ('4345a8b1-76f9-529a-be1d-cb2c9ff406a1'::uuid, '26487180-4429-5ca7-a85b-6c8d8acb4992'::uuid, 'La guerre commerciale entre les États-Unis et la Chine s’ouvre en…', 'mcq', '["2018","2008","2001","2022"]'::jsonb, 0, 'Droits de douane, puis contrôle des exportations de technologies.', 3),
    ('9e420a6f-6d00-5ad7-8ea7-d9c33fb1f68b'::uuid, '26487180-4429-5ca7-a85b-6c8d8acb4992'::uuid, 'Que désigne le friend-shoring ?', 'mcq', '["Produire chez des partenaires jugés fiables plutôt qu’au moins cher","Vendre uniquement à ses voisins","Délocaliser vers les pays les plus pauvres","Fermer ses frontières commerciales"]'::jsonb, 0, 'La sécurité d’approvisionnement passe avant le seul critère du coût.', 4),
    ('21fbeb40-b329-5258-bed7-48a7ffc2484f'::uuid, '26487180-4429-5ca7-a85b-6c8d8acb4992'::uuid, 'Le commerce mondial s’est effondré depuis 2020.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il se recompose et se régionalise : « recomposition » est plus juste que « démondialisation ».', 5),
