    ('09876197-e9d4-5817-9c2c-ef5066bb3e7a'::uuid, '92bdc65c-845e-53b4-a54f-72ef3ec86a51'::uuid, 'Quelle part du PIB français produit l’Île-de-France ?', 'mcq', '["Environ 31 %","Environ 15 %","Environ 50 %","Environ 20 %"]'::jsonb, 0, 'Pour environ 19 % de la population : une macrocéphalie sans équivalent proche en Europe.', 1),
